GEO_TABLES = ("assets", "catchments", "sensors", "observations", "forecasts", "scenes", "field_reports", "incidents", "proposals", "crews", "road_links")


def _postgis() -> None:
    """On PostgreSQL: enable PostGIS and add an indexed generated geometry column derived
    from the GeoJSON column (kept in sync by the database).  SQLite keeps GeoJSON + bbox."""
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS postgis")
    # pgvector is optional (labelled lexical fallback otherwise); do not fail the migration if the image lacks it.
    op.execute("DO $$ BEGIN CREATE EXTENSION IF NOT EXISTS vector; EXCEPTION WHEN OTHERS THEN RAISE NOTICE 'pgvector unavailable - lexical retrieval fallback'; END $$;")
    for t in GEO_TABLES:
        op.execute(f"ALTER TABLE {t} ADD COLUMN geom geometry(Geometry, 4326) GENERATED ALWAYS AS (CASE WHEN geometry IS NULL THEN NULL ELSE ST_SetSRID(ST_GeomFromGeoJSON(geometry::text), 4326) END) STORED")
        op.execute(f"CREATE INDEX ix_{t}_geom ON {t} USING GIST (geom)")


